dismissPath:"/settings/dismiss-notice/code_view_copilot_popover"}},userAccess:$R[364]={hasSubscriptionEnded:!1,orgHasCFBAccess:!1,userHasCFIAccess:!1,userHasOrgs:!1,userIsOrgAdmin:!1,userIsOrgMember:!1,business:null,featureRequestInfo:null}},copilotAccessAllowed:!1,copilotSpacesEnabled:!1,modelsAccessAllowed:!1,modelsRepoIntegrationEnabled:!1,isMarketplaceEnabled:!0}},dataUpdateCount:1,dataUpdatedAt:1792516188668,error:null,errorUpdateCount:0,errorUpdatedAt:0,fetchFailureCount:0,fetchFailureReason:null,fetchMeta:null,isInvalidated:!1,status:"success",fetchStatus:"idle"},queryKey:$R[256],queryHash:"[\"code-view\",\"codeViewBlobLayoutRoute\",\"\",\"mainQuery\",{\"pathname\":\"/Nacho-sh/multivariante/_layout/main/trabajo.r\"}]"},$R[365]={dehydratedAt:1792516188668,state:$R[366]={data:$R[367]={payload:$R[368]={"codeViewBlobLayoutRoute.StyledBlob":$R[369]={rawLines:$R[370]=["library(\"summarytools\")","library(\"ggplot2\")","library(\"ggpubr\")","library(\"foreign\")","library(\"readxl\")","library(\"archdata\")","library(\"psych\")","library(\"factoextra\")","library(\"scatterplot3d\")","library(\"tidyr\")","","","SLT \x3C- read_excel(\"Tarea_Glaucoma_DB.xlsx\", sheet = \"SLT\")","","class(SLT) #es dataframe","","names(SLT) \x3C- c(\"fechaslt\", \"sexo\", \"edad\", \"ojo\", \"glaucoma\", \"nimpactos\", \"cuadrantes\", ","                \"enerimpac\", \"enertotal\", \"cirugias\", \"piopre\", \"piosem\", \"piomes\", \"pio3mes\", ","                \"medprev\", \"medmes\", \"med3mes\", \"dolor\")","","sapply(SLT, class) #vemos de que tipo es cada variable","#Tenemos 8 variables numéricas. Además, el número de cuadrantes realizados, energía por impacto y ","#PIO el 1 mes se pueden convertir a numericos tambien. ","#es especialmente interesante el PIO al primer mes, asi que vamos a intentar convertirlo, pero antes habra que limpiarlo","","SLT$piomes \x3C- as.character(SLT$piomes)","SLT$piomes[SLT$piomes == \"\"] \x3C- NA            # vacíos -> NA","SLT$piomes \x3C- gsub(\",\", \".\", SLT$piomes)      # comas decimales -> punto","SLT$piomes \x3C- sub(\"[^0-9.].*$\", \"\", SLT$piomes)  # corta desde el primer carácter raro","SLT$piomes \x3C- as.numeric(SLT$piomes) #convertimos a numero","SLT$enerimpac\x3C- as.character(SLT$enerimpac)","SLT$enerimpac[SLT$enerimpac == \"\"] \x3C- NA            # vacíos -> NA","SLT$enerimpac \x3C- gsub(\",\", \".\", SLT$enerimpac)      # comas decimales -> punto","SLT$enerimpac \x3C- sub(\"[^0-9.].*$\", \"\", SLT$enerimpac)  # corta desde el primer carácter raro","SLT$enerimpac \x3C- as.numeric(SLT$enerimpac) #convertimos a numero","#vamos a ver si tenemos una muestra representativa de los distintos glaucomas o si tenemos que ajustar o descartar","","freq(SLT$glaucoma) #salvo 4 tipos de glaucomas, el resto solo tienen menos de tres observaciones, pero si nos fijamos,","#muchas de las categorias estan simplemente mal introducidas o son diagnosticos dudosos (como el que tiene \"?\").","#vamos a optar por limpiar manualmente estas categorias","SLT$glaucoma[SLT$glaucoma == \"GPPA\"] \x3C- \"GPAA\"","SLT$glaucoma[SLT$glaucoma == \"GPAA?\"] \x3C- \"GPAA\"","SLT$glaucoma[SLT$glaucoma == \"GCS\"] \x3C- \"GPAA\"","SLT$glaucoma[SLT$glaucoma == \"SD DISPERSION PIGMENTARIA\"] \x3C- \"PIGMENTARIO\"","SLT$glaucoma[SLT$glaucoma == \"GPAA?miópico\"] \x3C- \"GPAA\"","SLT$glaucoma[SLT$glaucoma == \"HTO PIGMENTARI\"] \x3C- \"PIGMENTARIO\"","SLT$glaucoma[SLT$glaucoma == \"GS PXE\"] \x3C- \"pseudoexfoliativo\"","SLT$glaucoma[SLT$glaucoma == \"G.PSEUDOEX\"] \x3C- \"pseudoexfoliativo\"","SLT$glaucoma[SLT$glaucoma == \"GLAUCO PIGMENT\"] \x3C- \"PIGMENTARIO\"","SLT$glaucoma[SLT$glaucoma == \"CPAC\"] \x3C- \"otros\"","SLT$glaucoma[SLT$glaucoma == \"GPAC\"] \x3C- \"otros\"","# por simplicidad y por falta de representacion, podemos agrupar glaucomas poco comunes como el congenito,","# postrabecular, GSAA o el miopico en una categoria de \"otros\"","SLT$glaucoma[SLT$glaucoma == \"GSAA\"] \x3C- \"otros\"","SLT$glaucoma[SLT$glaucoma == \"GLAUCOMA CONGENITO\"] \x3C- \"otros\"","SLT$glaucoma[SLT$glaucoma == \"GLAUCOMA POSTRABECULAR\"] \x3C- \"otros\"","SLT$glaucoma[SLT$glaucoma == \"miópico\"] \x3C- \"otros\"","freq(SLT$glaucoma) #los datos quedan mucho mas resumidos","descr(SLT)","summary(SLT)","#TODO: queremos añadir información de summary y descr como la desviacion tipica pero en descr hay demasiados datos","#VISUALES ","#En esta parte, dibujamos histogramas, boxplots, diagramas de barras y 'piecharts' para ver como","# son los SLT con los que estamos trabajando ","#2 Tipo de glaucoma","","p1 \x3C- ggplot(SLT, aes(x= factor(1), fill = `glaucoma`))+","  geom_bar() + coord_polar(\"y\") + labs(x = \"glaucoma\", y = \"%\") + theme_void()","","ggarrange(p1,nrow = 1, common.legend = TRUE)","","","#3 Nº de impactos ","","p1 \x3C- ggplot(SLT, aes(x = `nimpactos`))+geom_density(fill = \"skyblue\", alpha = 0.6) + ","  labs(title = \"Densidad\", x = \"nimpactos\", y = \"Densidad\") + theme_bw()","","p2 \x3C- ggplot(SLT,aes(x = `nimpactos`)) + geom_histogram(bins = 15, fill = \"green\", color = \"white\") +","  labs(title = \"Histograma\", x = \"nimpactos\", y = \"Frecuencia\") + theme_bw()","","p3 \x3C- ggplot(SLT, aes(x = `nimpactos`)) + geom_boxplot(outlier.colour = \"red\", outlier.shape = 1, outlier.size = 3) +","  coord_flip() +","  labs(title = \"Boxplot\", x = \"Valor\", y = \"\") + theme_bw()","","ggarrange(p1,p2,p3, nrow = 1, common.legend = FALSE)","","#5 enerimpac","","","p1 \x3C- ggplot(SLT, aes(x = `enerimpac`)) + geom_boxplot(outlier.colour = \"red\", outlier.shape = 1, outlier.size = 3) +","  coord_flip() +","  labs(title = \"Boxplot\", x = \"Valor\", y = \"\") + theme_bw()","","ggarrange(p1, nrow = 1, common.legend = FALSE)","","","#6 Energía total","","p1 \x3C- ggplot(SLT, aes(x = `enertotal`))+geom_density(fill = \"skyblue\", alpha = 0.6) + ","  labs(title = \"Densidad\", x = \"enertotal\", y = \"Densidad\") + theme_bw()","","","p2 \x3C- ggplot(SLT, aes(x = `enertotal`)) + geom_boxplot(outlier.colour = \"red\", outlier.shape = 1, outlier.size = 3) +","  coord_flip() +","  labs(title = \"Boxplot\", x = \"Valor\", y = \"\") + theme_bw()","","p3 \x3C- ggplot(SLT,aes(x = `enertotal`)) + geom_histogram(bins = 15, fill = \"green\", color = \"white\") +","  labs(title = \"Histograma\", x = \"enertotal\", y = \"Frecuencia\") + theme_bw()","","ggarrange(p1,p2,p3, nrow = 1, common.legend = FALSE)","#TODO: dejamos o quitamos los graficos de nimpactos, enertotal y enerimpac? Tener en cuenta que dependen ","#funcionalmente dos a uno","","#7 Cirugia previa","#TODO: limpiar estos datos y decir que la mayoria son primerizos","p1 \x3C- ggplot(SLT, aes(x= factor(1), fill = `cirugias`))+","  geom_bar() + coord_polar(\"y\") + labs(x = \"cirugias\", y = \"%\") + theme_void()","","ggarrange(p1,nrow = 1, common.legend = TRUE)","","#8 PIO PRE STL","#TODO: meter una raya vertical en 22 y decir que la mayoria si necesitan como minimo tratamiento. Hacer esto para ","#piosem, piomes, pio3mes","p1 \x3C- ggplot(SLT, aes(x = `piopre`))+geom_density(fill = \"skyblue\", alpha = 0.6) + ","  labs(title = \"Densidad\", x = \"piopre\", y = \"Densidad\") + theme_bw()","","p2 \x3C- ggplot(SLT, aes(x = `piopre`)) + geom_boxplot(outlier.colour = \"red\", outlier.shape = 1, outlier.size = 3) +","  coord_flip() +","  labs(title = \"Boxplot\", x = \"Valor\", y = \"\") + theme_bw()","","ggarrange(p1,p2, nrow = 1, common.legend = FALSE)","","#9 piosem","","p1 \x3C- ggplot(SLT, aes(x = `piosem`))+geom_density(fill = \"skyblue\", alpha = 0.6) + ","  labs(title = \"Densidad\", x = \"piosem\", y = \"Densidad\") + theme_bw()","","p2 \x3C- ggplot(SLT,aes(x = `piosem`)) + geom_histogram(bins = 15, fill = \"green\", color = \"white\") +","  labs(title = \"Histograma\", x = \"piosem\", y = \"Frecuencia\") + theme_bw()","","p3 \x3C- ggplot(SLT, aes(x = `piosem`)) + geom_boxplot(outlier.colour = \"red\", outlier.shape = 1, outlier.size = 3) +","  coord_flip() +","  labs(title = \"Boxplot\", x = \"Valor\", y = \"\") + theme_bw()","","ggarrange(p1,p2,p3, nrow = 1, common.legend = FALSE)","","#10 piomes","","p1 \x3C- ggplot(SLT, aes(x = `piomes`))+geom_density(fill = \"skyblue\", alpha = 0.6) + ","  labs(title = \"Densidad\", x = \"piomes\", y = \"Densidad\") + theme_bw()","","p2 \x3C- ggplot(SLT,aes(x = `piomes`)) + geom_histogram(bins = 15, fill = \"green\", color = \"white\") +","  labs(title = \"Histograma\", x = \"piomes\", y = \"Frecuencia\") + theme_bw()","","p3 \x3C- ggplot(SLT, aes(x = `piomes`)) + geom_boxplot(outlier.colour = \"red\", outlier.shape = 1, outlier.size = 3) +","  coord_flip() +","  labs(title = \"Boxplot\", x = \"Valor\", y = \"\") + theme_bw()","","ggarrange(p1,p2,p3, nrow = 1, common.legend = FALSE)","","","#11 pio3mes","","p1 \x3C- ggplot(SLT, aes(x = `pio3mes`))+geom_density(fill = \"skyblue\", alpha = 0.6) + ","  labs(title = \"Densidad\", x = \"pio3mes\", y = \"Densidad\") + theme_bw()","","p2 \x3C- ggplot(SLT,aes(x = `pio3mes`)) + geom_histogram(bins = 15, fill = \"green\", color = \"white\") +","  labs(title = \"Histograma\", x = \"pio3mes\", y = \"Frecuencia\") + theme_bw()","","p3 \x3C- ggplot(SLT, aes(x = `pio3mes`)) + geom_boxplot(outlier.colour = \"red\", outlier.shape = 1, outlier.size = 3) +","  coord_flip() +","  labs(title = \"Boxplot\", x = \"Valor\", y = \"\") + theme_bw()","","ggarrange(p1,p2,p3, nrow = 1, common.legend = FALSE)","","","#12 Fármacos pre SLT","#TODO: hablar si quitar todos los graficos de los medicamentos","p1 \x3C- ggplot(SLT, aes(x= factor(1), fill = `medprev`))+","  geom_bar() + coord_polar(\"y\") + labs(x = \"medprev\", y = \"%\") + theme_void()","","p2 \x3C- ggplot(SLT,aes(x = `medprev`, fill = `medprev`)) + geom_bar() + labs(x = \"medprev\", y = \"Frecuencia\")","","ggarrange(p1,p2,nrow = 1, common.legend = TRUE)","","#13 Fármacos 1er Mes","","p1 \x3C- ggplot(SLT, aes(x= factor(1), fill = factor(`medmes`)))+","  geom_bar() + coord_polar(\"y\") + labs(x = \"medmes\", y = \"%\") + theme_void()","","p2 \x3C- ggplot(SLT,aes(x = `medmes`, fill = factor(`medmes`))) + geom_bar() + labs(x = \"medmes\", y = \"Frecuencia\")","","ggarrange(p1,p2,nrow = 1, common.legend = TRUE)","","#14 Fármacos 3er Mes","","p1 \x3C- ggplot(SLT, aes(x= factor(1), fill = factor(`med3mes`)))+","  geom_bar() + coord_polar(\"y\") + labs(x = \"med3mes\", y = \"%\") + theme_void()","","p2 \x3C- ggplot(SLT,aes(x = `med3mes`, fill = factor(`med3mes`))) + geom_bar() + labs(x = \"med3mes\", y = \"Frecuencia\")","","ggarrange(p1,p2,nrow = 1, common.legend = TRUE)","","","# podemos estudiar la evolución media del PIO de cada glaucoma a lo largo del tiempo. A menor PIO, mayor mejoría","#esta parte yo no se hacerla, lo he estado intentando un rato y no termino de entender por que es tan complicada ","#y larga de hacer. copiado de deepseek","medias_evolucion \x3C- data.frame(","  Pre      = tapply(SLT$piopre,  SLT$glaucoma, mean, na.rm = TRUE), #na.rm ignora los NA","  Sem1     = tapply(SLT$piosem, SLT$glaucoma, mean, na.rm = TRUE),","  Mes1     = tapply(SLT$piomes, SLT$glaucoma, mean, na.rm = TRUE),","  Mes3     = tapply(SLT$pio3mes, SLT$glaucoma, mean, na.rm = TRUE)",")","medias_evolucion","# Convertir rownames a columna","medias_evolucion$glaucoma \x3C- rownames(medias_evolucion)","","# Pasar de ancho a largo con stack() o reshape","medias_largo \x3C- reshape(","  medias_evolucion,","  varying = c(\"Pre\", \"Sem1\", \"Mes1\", \"Mes3\"),","  v.names = \"media\",","  timevar = \"momento\",","  times   = c(\"Pre\", \"Sem1\", \"Mes1\", \"Mes3\"),","  direction = \"long\"",")","","# 3. Quitar la columna \"id\" que añade reshape","medias_largo$id \x3C- NULL","rownames(medias_largo) \x3C- NULL","medias_largo","medias_largo$momento \x3C- factor(medias_largo$momento,","                               levels = c(\"Pre\", \"Sem1\", \"Mes1\", \"Mes3\"))","ggplot(medias_largo, aes(x = momento, y = media,","                         color = glaucoma, group = glaucoma)) +","  geom_line()","medias_largo","#TODO: añadir el grafico pero para los porcentajes","#TODO: añadir aclaracion de que pseudoexfoliativo tiene muy pocos datos realmente","# parece que hay glaucomas que curan mejor que otros, el GPPA a lo mejor necesita mas tratamiento postop","# vamos a ver si existe una correlacion sustancial entre el tipo de glaucoma y la mejoria","# para justamente esto era el test ANOVA","","anova(lm(piopre ~ glaucoma, data = SLT))","anova(lm(piosem ~ glaucoma, data = SLT))","anova(lm(piomes ~ glaucoma, data = SLT))","anova(lm(pio3mes ~ glaucoma, data = SLT))","# pues no, parece que en ninguno de los grupos podemos rechazar que la media sea distinta en ","# ningun punto del seguimiento. a los 3 meses estamos a punto de concluir que las medias si que cambian (p=0.058)","# si nos la jugamos, podemos concluir que las medias cambian. yo no me la jugaria, es un resultado borderline","","# vamos a dar otro enfoque. veamos si hay outliers en las distintas categorias","# podemos verlo con los distintos PIO para cada glaucoma","freq(SLT$glaucoma)","SLT$id \x3C- 1:nrow(SLT)","# TODO: ver que hacemos con los GCS ","SLT_largo \x3C- SLT %>%","  pivot_longer(","    cols = c(piopre, piosem, piomes, pio3mes),","    names_to = \"momento\",","    values_to = \"pio\"","  ) %>%","  mutate(momento = factor(momento,","                          levels = c(\"piopre\", \"piosem\", \"piomes\", \"pio3mes\"),","                          labels = c(\"Pre\", \"Sem1\", \"Mes1\", \"Mes3\")))","# Densidad por momento","p1 \x3C- ggplot(SLT_largo, aes(x = pio, fill = momento)) +","  geom_density(alpha = 0.4) +","  facet_wrap(~ momento, nrow = 1, scales = \"free_y\") +","  labs(x = \"PIO (mmHg)\", y = \"Densidad\", title = \"Densidad por momento\") +","  theme_bw() +","  theme(legend.position = \"none\")","","# Boxplot por momento","p2 \x3C- ggplot(SLT_largo, aes(x = momento, y = pio, fill = momento)) +","  geom_boxplot(outlier.colour = \"red\", outlier.shape = 1, outlier.size = 2) +","  labs(x = \"Momento\", y = \"PIO (mmHg)\", title = \"Boxplot por momento\") +","  theme_bw() +","  theme(legend.position = \"none\")","","ggarrange(p1, p2, nrow = 2)","","#TODO: aqui se ve que en el mes1 hay una mala medicion porque hay 0 de pio en un unico paciente","#vamos a sustituir los outliers por el cuartil más próximo en cada momento","outlier \x3C- function(x) {","  H  \x3C- 1.5 * IQR(x, na.rm = TRUE)","  q1 \x3C- quantile(x, 0.25, na.rm = TRUE)","  q3 \x3C- quantile(x, 0.75, na.rm = TRUE)","  x[x \x3C q1 - H] \x3C- q1","  x[x > q3 + H] \x3C- q3","  x[is.na(x)] \x3C- mean(x, na.rm = TRUE) #TODO: probar a comentar esta linea","  x","}","","SLT$piopre \x3C- outlier(SLT$piopre)","SLT$piosem \x3C- outlier(SLT$piosem)","SLT$piomes \x3C- outlier(SLT$piomes)","SLT$pio3mes \x3C- outlier(SLT$pio3mes)","SLT$nimpactos \x3C- outlier(SLT$piopre)","SLT$enertotal \x3C- outlier(SLT$piosem)","SLT$enerimpac \x3C- outlier(SLT$piomes)","#TODO: repetir los graficos quitando outliers (ver si lo dejamos o no)","p1 \x3C- ggplot(SLT_largo, aes(x = pio, fill = momento)) +","  geom_density(alpha = 0.4) +","  facet_wrap(~ momento, nrow = 1, scales = \"free_y\") +","  labs(x = \"PIO (mmHg)\", y = \"Densidad\", title = \"Densidad por momento\") +","  theme_bw() +","  theme(legend.position = \"none\")","","# Boxplot por momento","p2 \x3C- ggplot(SLT_largo, aes(x = momento, y = pio, fill = momento)) +","  geom_boxplot(outlier.colour = \"red\", outlier.shape = 1, outlier.size = 2) +","  labs(x = \"Momento\", y = \"PIO (mmHg)\", title = \"Boxplot por momento\") +","  theme_bw() +","  theme(legend.position = \"none\")","","ggarrange(p1, p2, nrow = 2)","","###############################################################################","# BLOQUE 8. PCA (ANÁLISIS DE COMPONENTES PRINCIPALES)","# -----------------------------------------------------------------------------","# ¿Qué hace el PCA?","#   Crea NUEVAS variables (componentes) que son combinaciones lineales de las","#   originales. La 1ª componente (PC1) recoge la mayor varianza posible, la","#   2ª (PC2) recoge la mayor varianza restante y es perpendicular a PC1, etc.","#","# ¿Para qué sirve?","#   - Reducir muchas variables a unas pocas.","#   - Ver qué variables van juntas (correlacionadas).","#   - Visualizar pacientes en 2D.","#","# Parámetros:","#   scale  = TRUE -> estandariza (cada variable media 0, sd 1).","#                    IMPORTANTE si las variables tienen escalas distintas.","#   center = TRUE -> centra en la media.","###############################################################################","SLT$enerimpac \x3C- as.character(SLT$enerimpac)","SLT$enerimpac[SLT$enerimpac == \"\"] \x3C- NA            # vacíos -> NA","SLT$enerimpac \x3C- gsub(\",\", \".\", SLT$enerimpac)      # comas decimales -> punto","SLT$enerimpac \x3C- sub(\"[^0-9.].*$\", \"\", SLT$enerimpac)  # corta desde el primer carácter raro","SLT$enerimpac \x3C- as.numeric(SLT$enerimpac) #convertimos a numero","pca \x3C- prcomp(SLT[, c(6,8,9,11:14)], scale = TRUE, center = TRUE)","descr(SLT)","# \"rotation\": cuánto pesa cada variable original en cada componente (loadings)","pca$rotation","","# \"sdev\": desviación típica de cada componente. Al cuadrado = varianza.","pca$sdev","","# Resumen: proporción de varianza explicada por cada componente","summary(pca)","","# Varianza explicada (proporción)","var_expl \x3C- pca$sdev^2 / sum(pca$sdev^2)","var_expl","","# Varianza acumulada","cum_var \x3C- cumsum(var_expl)","cum_var","#TODO: hacer el test del det de la matriz de corr para ver si tiene sentido hacer PCA","###############################################################################","# BLOQUE 9. GRÁFICOS DEL PCA","# -----------------------------------------------------------------------------","# 1) Varianza explicada por componente (scree plot):","#    Muestra cuánta info aporta cada componente. Se eligen las que van antes","#    del \"codo\" (donde la curva se aplana), o las que superan la media de","#    varianza (1/nº de variables si estandarizamos).","#","# 2) fviz_pca_var: dibuja las VARIABLES como flechas.","#    - Flechas en la misma dirección = variables correlacionadas positivamente.","#    - Flechas opuestas = correlación negativa.","#    - Flechas perpendiculares = poca relación.","#    - Color \"cos2\" = calidad de representación (más oscuro = mejor).","#","# 3) fviz_pca_ind: dibuja los INDIVIDUOS (filas).","#    - Puntos cercanos = perfiles parecidos.","#    - Color \"contrib\" = cuánto contribuye cada punto a la componente.","#","# 4) fviz_pca: biplot, variables + individuos juntos.","###############################################################################","","# Screenplot","df_var \x3C- data.frame(pc = 1:length(var_expl), var = var_expl)","p1 \x3C- ggplot(df_var, aes(x = pc, y = var, fill = var)) +","  geom_col(width = 0.4) +","  theme_bw() +","  labs(x = \"Componente principal\", y = \"Proporción de varianza\")","","# Varianza acumulada","df_cum \x3C- data.frame(pc = 1:length(cum_var), cum = cum_var)","p2 \x3C- ggplot(df_cum, aes(x = pc, y = cum, fill = cum)) +","  geom_col(width = 0.4) +","  scale_y_continuous(limits = c(0, 1)) +","  theme_bw() +","  labs(x = \"Componente principal\", y = \"Varianza acumulada\")","","ggarrange(p1, p2, nrow = 1)","","","# Gráficos de variables (flechas)","fviz_pca_var(pca, repel = TRUE, col.var = \"cos2\",","             legend.title = \"cos2\", title = \"Variables en PC1-PC2\") +","  theme_bw()","","fviz_pca_var(pca, axes = c(1, 3), repel = TRUE, col.var = \"cos2\",","             title = \"Variables en PC1-PC3\") +","  theme_bw()","","fviz_pca_var(pca, axes = c(2, 3), repel = TRUE, col.var = \"cos2\",","             title = \"Variables en PC2-PC3\") +","  theme_bw()","descr(SLT)","","# Gráficos de individuos","fviz_pca_ind(pca, col.ind = \"contrib\",","             gradient.cols = c(\"#00AFBB\", \"#E7B800\", \"#FC4E07\"),","             repel = TRUE, legend.title = \"Contrib.\", title = \"Individuos\") +","  theme_bw()","","fviz_pca_ind(pca, axes = c(1, 3), col.ind = \"contrib\",","             gradient.cols = c(\"#00AFBB\", \"#E7B800\", \"#FC4E07\"),","             repel = TRUE, title = \"Individuos PC1-PC3\") +","  theme_bw()","","","# Biplot: variables + individuos","fviz_pca(pca, alpha.ind = \"contrib\", col.var = \"cos2\",","         col.ind = \"seagreen\",","         gradient.cols = c(\"#FDF50E\", \"#FD960E\", \"#FD1E0E\"),","         repel = TRUE, legend.title = \"Distancia\") +","  theme_bw()"],colorizedLines:null,stylingDirectives:$R[371]={format:"compact",lineOffsets:$R[372]=[0,3,6,9,12,15,18,21,24,27,30,30,30,40,40,43,43,66,87,99,99,103,105,107,109,109,116,130,145,160,169,176,190,205,220,229,231,231,236,238,240,254,268,282,296,310,324,338,352,366,380,394,396,398,412,426,440,454,459,460,461,463,465,467,469,471,471,482,498,498,505,505,505,507,507,523,539,539,560,576,576,595,596,612,612,621,621,623,623,623,642,643,659,659,666,666,666,668,668,684,700,700,700,719,720,736,736,757,773,773,782,784,786,786,788,790,801,817,817,824,824,826,828,830,846,862,862,881,882,898,898,906,906,908,908,924,940,940,961,977,977,996,997,1013,1013,1022,1022,1024,1024,1040,1056,1056,1077,1093,1093,1112,1113,1129,1129,1138,1138,1138,1140,1140,1156,1172,1172,1193,1209,1209,1228,1229,1245,1245,1254,1254,1254,1256,1258,1269,1285,1285,1306,1306,1314,1314,1316,1316,1328,1344,1344,1366,1366,1374,1374,1376,1376,1388,1404,1404,1426,1426,1434,1434,1434,1436,1438,1440,1443,1457,1469,1481,1493,1493,1494,1496,1501,1501,1503,1505,1506,1520,1525,1530,1544,1549,1549,1549,1551,1556,1559,1560,1568,1582,1589,1596,1596,1597,1599,1601,1603,1605,1607,1607,1613,1619,1625,1631,1633,1635,1637,1637,1639,1641,1644,1651,1653,1657,1657,1663,1668,1673,1674,1678,1692,1706,1708,1718,1722,1733,1749,1750,1755,1755,1757,1770,1782,1798,1799,1804,1804,1809,1809,1811,1813,1817,1825,1832,1839,1847,1855,1864,1865,1865,1865,1872,1879,1886,1893,1900,1907,1914,1916,1926,1930,1941,1957,1958,1963,1963,1965,1978,1990,2006,2007,2012,2012,2017,2017,2019,2021,2023,2025,2027,2029,203